def romanToInt(s: str) -> int:
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
              'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i in range(len(s)):
        if i + 1 < len(s) and values[s[i]] < values[s[i + 1]]:
            total -= values[s[i]]
        else:
            total += values[s[i]]
    return total

def intToRoman(num: int) -> str:
    mapping = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]
    result = ""
    for value, symbol in mapping:
        while num >= value:
            result += symbol
            num -= value
    return result

def main():
    print("=" * 40)
    print("  Welcome to the Roman ↔ Integer Converter")
    print("=" * 40)

    while True:
        try:
            print("\nChoose an option:")
            print("1 - Convert Roman to Integer")
            print("2 - Convert Integer to Roman")
            choice = input("Enter your choice (1 or 2): ").strip()

            if choice == "1":
                roman = input("Enter a Roman numeral: ").upper().strip()
                if not all(ch in "IVXLCDM" for ch in roman):
                    raise ValueError("Invalid Roman numeral characters.")
                result = romanToInt(roman)
                print(f"✅ Roman '{roman}' = Integer {result}")

            elif choice == "2":
                num_str = input("Enter an integer (1–3999): ").strip()
                if not num_str.isdigit():
                    raise ValueError("Input must be a positive integer.")
                num = int(num_str)
                if not (1 <= num <= 3999):
                    raise ValueError("Integer must be between 1 and 3999.")
                result = intToRoman(num)
                print(f"✅ Integer {num} = Roman '{result}'")

            else:
                raise ValueError("Invalid menu choice.")

        except ValueError as e:
            print(f"❌ Error: {e}")
        except Exception as e:
            print(f"⚠ Unexpected error: {e}")

        again = input("\nDo you want to try again? (y/n): ").strip().lower()
        if again != "y":
            print("\nThank you for using the converter. Goodbye! 👋")
            break
